63	// ListRegistryTags lists the tags of a repository through the registry's v2 API.
64	//
65	// apiURL is the API base (see the browser's registryAPIURL). Credentials, when
66	// given, go as Basic auth and, on a 401 that names a Bearer realm, to that
67	// realm's token endpoint — the flow Docker Hub and most hosted registries use.
68	// The token is kept for the following pages.
69	//
70	// The list is followed across pages: whatever a registry caps a response at,
71	// and Docker Hub does not, a repository with more tags than one page holds is
72	// returned whole. This is the one tag lister that speaks the Bearer flow; the
73	// template client's ListTags (Client.ListTags) reads a registry the user
74	// configured for templates and only ever sends Basic auth.
75	func ListRegistryTags(apiURL, repo, username, password string) ([]string, error) {
76		next := fmt.Sprintf("%s/v2/%s/tags/list", strings.TrimSuffix(apiURL, "/"), repo)
77		var (
78			tags  []string
79			token string
80		)
81		for page := 0; next != ""; page++ {
82			if page == maxTagPages {
83				return nil, fmt.Errorf("tag list of %s is longer than %d pages", repo, maxTagPages)
84			}
85			body, link, usedToken, err := registryGET(next, username, password, token)
86			if err != nil {
87				return nil, err
88			}
89			token = usedToken
90			var result struct {
91				Tags []string `json:"tags"`
92			}
93			if err := json.Unmarshal(body, &result); err != nil {
94				return nil, fmt.Errorf("decode tags response: %w", err)
95			}
96			tags = append(tags, result.Tags...)
97			next = resolveNext(next, link)
98		}
99		return tags, nil
100	}
101	
102	// registryGET performs a GET, answering a Bearer challenge once. It returns the
103	// body, the Link header, and the token to send on the following requests.
104	func registryGET(rawURL, username, password, token string) (body []byte, link, usedToken string, err error) {
105		resp, token, err := registryDo(http.MethodGet, rawURL, "", username, password, token)
106		if err != nil {
107			return nil, "", token, err
108		}
109		defer func() { _ = resp.Body.Close() }()
110		if resp.StatusCode != http.StatusOK {
111			return nil, "", token, &StatusError{Code: resp.StatusCode, Source: SourceRegistry}
112		}
113		body, err = io.ReadAll(io.LimitReader(resp.Body, maxTagResponse))
114		return body, resp.Header.Get("Link"), token, err
115	}
116	
117	// registryDo sends one request, answering a Bearer challenge once. The caller
118	// closes the response body and reads the status.
119	func registryDo(method, rawURL, accept, username, password, token string) (*http.Response, string, error) {
120		resp, err := doRequest(method, rawURL, accept, username, password, token)
121		if err != nil {
122			return nil, token, err
123		}
124		if resp.StatusCode != http.StatusUnauthorized {
125			return resp, token, nil
126		}
127		challenge := resp.Header.Get("Www-Authenticate")
128		_ = resp.Body.Close()
129		if !strings.HasPrefix(challenge, "Bearer ") {
130			return nil, token, &StatusError{Code: http.StatusUnauthorized, Source: SourceRegistry, Challenge: challenge, unexpectedChallenge: true}
131		}
132		token, err = exchangeBearerToken(challenge[7:], username, password)
133		if err != nil {
134			return nil, "", err
135		}
136		if resp, err = doRequest(method, rawURL, accept, "", "", token); err != nil {
137			return nil, token, fmt.Errorf("%s (retry) %s: %w", method, rawURL, err)
138		}
139		return resp, token, nil
140	}
141	
142	// doRequest sends one request: a bearer token when there is one, Basic auth
143	// when there are credentials and no token.
144	func doRequest(method, rawURL, accept, username, password, token string) (*http.Response, error) {
145		req, err := http.NewRequest(method, rawURL, nil)
146		if err != nil {
147			return nil, fmt.Errorf("build request: %w", err)
148		}
149		if accept != "" {
150			req.Header.Set("Accept", accept)
151		}
152		switch {
153		case token != "":
154			req.Header.Set("Authorization", "Bearer "+token)
155		case username != "" && password != "":
156			req.SetBasicAuth(username, password)
157		}
158		resp, err := registryHTTPClient.Do(req)
159		if err != nil {
160			return nil, fmt.Errorf("%s %s: %w", method, rawURL, err)
161		}
162		return resp, nil
163	}
164	
165	// manifestAccept lists every manifest kind a tag can point to. A multi-platform
166	// tag is an index (or a Docker manifest list), and its digest is the one `docker
167	// pull` records in RepoDigests; asking for a single-platform manifest only
168	// would make the registry convert or refuse, and the digests would not match.
169	var manifestAccept = strings.Join([]string{
170		"application/vnd.oci.image.index.v1+json",
171		"application/vnd.docker.distribution.manifest.list.v2+json",
172		"application/vnd.oci.image.manifest.v1+json",
173		"application/vnd.docker.distribution.manifest.v2+json",
174	}, ", ")
175	
176	// ManifestDigest returns the digest a tag currently points to, from the
177	// registry's Docker-Content-Digest header.
178	//
179	// It is a HEAD request: Docker Hub does not count a HEAD against the pull rate
180	// limit, and nothing but the header is needed.
181	func ManifestDigest(apiURL, repo, tag, username, password string) (string, error) {
182		rawURL := fmt.Sprintf("%s/v2/%s/manifests/%s", strings.TrimSuffix(apiURL, "/"), repo, url.PathEscape(tag))
183		resp, _, err := registryDo(http.MethodHead, rawURL, manifestAccept, username, password, "")
184		if err != nil {
185			return "", err
186		}
187		_ = resp.Body.Close()
188		if resp.StatusCode != http.StatusOK {
189			return "", fmt.Errorf("registry returned %d for %s:%s", resp.StatusCode, repo, tag)
190		}
191		digest := resp.Header.Get("Docker-Content-Digest")
192		if digest == "" {
193			return "", fmt.Errorf("registry gave no digest for %s:%s", repo, tag)
194		}
195		return digest, nil
196	}
197	
198	// RegistryAPIBase is the v2 API root of a registry named in an image reference:
199	// Docker Hub has its own host, a local registry is reached over plain HTTP, and
200	// everything else over HTTPS. An empty registry is Docker Hub.
201	func RegistryAPIBase(registry string) string {
202		switch {
203		case registry == "":
204			return "https://registry-1.docker.io"
205		case strings.HasPrefix(registry, "localhost") || strings.HasPrefix(registry, "127.0.0.1"):
206			return "http://" + registry
207		}
208		return "https://" + registry
209	}
210	
211	// resolveNext is the URL a Link header's rel="next" points to, resolved against
212	// the page it came with — registries send it as a path — or "" when there is
213	// none. A next link that leads back to the page just read ends the walk rather
214	// than looping on it.
215	func resolveNext(current, link string) string {
216		for _, part := range strings.Split(link, ",") {
217			target, rel, ok := strings.Cut(strings.TrimSpace(part), ";")
218			if !ok || !strings.Contains(rel, `rel="next"`) {
219				continue
220			}
221			target = strings.Trim(strings.TrimSpace(target), "<>")
222			base, err := url.Parse(current)
223			if err != nil {
224				return ""
225			}
226			ref, err := url.Parse(target)
227			if err != nil {
228				return ""
229			}
230			if next := base.ResolveReference(ref).String(); next != current {
231				return next
232			}
233		}
234		return ""
235	}
236	
237	// exchangeBearerToken fetches a bearer token from the registry's token endpoint.
238	func exchangeBearerToken(challenge, username, password string) (string, error) {
239		params := parseBearerChallenge(challenge)
240		realm, ok := params["realm"]
241		if !ok {
242			return "", fmt.Errorf("bearer challenge missing realm")
243		}
244		u, err := url.Parse(realm)
245		if err != nil {
246			return "", fmt.Errorf("parse realm %q: %w", realm, err)
247		}
248		q := u.Query()
249		if s, ok := params["service"]; ok {
250			q.Set("service", s)
251		}
252		if s, ok := params["scope"]; ok {
253			q.Set("scope", s)
254		}
255		u.RawQuery = q.Encode()
256	
257		req, err := http.NewRequest("GET", u.String(), nil)
258		if err != nil {
259			return "", fmt.Errorf("build token request: %w", err)
260		}
261		if username != "" && password != "" {
262			req.SetBasicAuth(username, password)
263		}
264		resp, err := registryHTTPClient.Do(req)
265		if err != nil {
266			return "", fmt.Errorf("fetch token: %w", err)
267		}
268		defer func() { _ = resp.Body.Close() }()
269		if resp.StatusCode != http.StatusOK {
270			return "", &StatusError{Code: resp.StatusCode, Source: SourceToken}
271		}
272		body, err := io.ReadAll(resp.Body)
273		if err != nil {
274			return "", fmt.Errorf("read token response: %w", err)
275		}
276		var result struct {
277			Token       string `json:"token"`
278			AccessToken string `json:"access_token"`
279		}
280		if err := json.Unmarshal(body, &result); err != nil {
281			return "", fmt.Errorf("decode token response: %w", err)
282		}
283		if result.Token != "" {
284			return result.Token, nil
285		}
286		if result.AccessToken != "" {
287			return result.AccessToken, nil
288		}
289		return "", fmt.Errorf("token response contained no token field")

